import{_ as t,o as a,c as i,a as o}from"./app.BAI08CEQ.js";const h=JSON.parse('{"title":"ADR-017: Unified Quality Control Plane","description":"","frontmatter":{},"headers":[],"relativePath":"reference/ADR-017-unified-quality-control-plane.md","filePath":"reference/ADR-017-unified-quality-control-plane.md","lastUpdated":1771803666000}'),l={name:"reference/ADR-017-unified-quality-control-plane.md"};function n(r,e,c,s,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-017-unified-quality-control-plane" tabindex="-1">ADR-017: Unified Quality Control Plane <a class="header-anchor" href="#adr-017-unified-quality-control-plane" aria-label="Permalink to &quot;ADR-017: Unified Quality Control Plane&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-02-22</li><li>Owner: quality-platform</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>thegent</code> now has a growing set of quality signals:</p><ul><li>hook result envelopes (<code>quality-gate</code>, <code>security-pipeline</code>)</li><li>SARIF export bridge</li><li>generated-code anti-pattern checker</li><li>mutation/perf pilot artifacts</li></ul><p>Without one control-plane decision, policy behavior drifts between local lanes and CI.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use <strong>GitHub+SARIF-native</strong> as the default control plane for unified quality in 2026.</p><ul><li>Canonical transport: SARIF + JSON side artifacts</li><li>Canonical policy input: contract-backed artifacts under <code>artifacts/quality</code> and <code>artifacts/hooks</code></li><li>Sonar remains optional as a downstream adapter, not source-of-truth</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><ul><li>Lowest integration friction with existing GitHub checks and code-scanning workflows.</li><li>Works with multi-tool and custom checker outputs uniformly.</li><li>Keeps internal contracts explicit and portable, independent of vendor lock-in.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Every new checker must define: <ul><li>JSON artifact contract</li><li>optional SARIF adapter</li><li>deterministic task entry in <code>Taskfile.yml</code></li></ul></li><li>CI promotion gates will consume contract-validated artifacts.</li><li>Future Sonar integration should ingest from these artifacts, not bypass them.</li></ul><h2 id="rollout" tabindex="-1">Rollout <a class="header-anchor" href="#rollout" aria-label="Permalink to &quot;Rollout&quot;">​</a></h2><ol><li>Enforce control-plane policy contract in quality lanes.</li><li>Aggregate hook/checker artifacts into one quality summary artifact.</li><li>Promote non-blocking pilots to required checks after stability windows.</li></ol>',15)])])}const p=t(l,[["render",n]]);export{h as __pageData,p as default};
